  const items = Array.from(els, (el) => ({ el, t: el.querySelector(':scope > .accent-text'), tight: el.classList.contains('accent') && el.closest('.hero-title') !== null, y: undefined, top: 0, grad: '' }));
  function update() {
    const vh = window.innerHeight;
    if (vh === 0) return;
    for (const it of items) it.top = it.el.getBoundingClientRect().top;
    for (const it of items) {
      const elTopVh = (it.top / vh) * 100;
      const targetY = 50 - elTopVh;
      const prevY = it.y === undefined ? targetY : it.y;
      const nextY = prevY + (targetY - prevY) * LERP;
      it.y = nextY;
      const tight = it.tight;
      const grad = `radial-gradient(circle at 50% ${nextY.toFixed(2)}vh,` + ` #ff8b6b 0vh,` + ` #ff1727 ${tight ? 12 : 30}vh,` + ` #6B0808 ${tight ? 50 : 80}vh,` + ` #1F0202 ${tight ? 120 : 160}vh)`;
